var e={B1:JSON.parse(`{"title":"استماع","heading":"اسمع كل أجهزة البلوتوث من حولك","goal":"الهواتف والساعات وسماعات الأذن ومكبرات الصوت ولوحات المفاتيح والمنارات تعلن عن نفسها طوال اليوم: حزم <b>إعلان</b> (advertising) قصيرة على ثلاث قنوات لاسلكية، عدة مرات في الثانية، سواء كان أحد يستمع أم لا. يحوّل B1 اللوحة إلى مستمع. يرسم الأجهزة على رادار، ويخمّن نوع كل جهاز، ويفكك الحزمة بايتًا بايتًا. يستخدم الراديو NimBLE، وهو حزمة بلوتوث خفيفة؛ والبرنامج الثابت خاص بالمختبر (<code>ble-lab-b1</code>)، مع شيفرة مشتركة في <code>kit/lib/ble-kit</code>.","goalLine":"اعثر على هاتفك بين الأجهزة من حولك، واقرأ حزمه بايتًا بايتًا، وقِس عدد مرات إعلانه.","goalCheck":["يعرض <b>الرادار</b> نقاطًا، ويطبع الأمر <code>list</code> في المراقب جدولًا بالأجهزة مع نوع كل جهاز (هاتف، صوت، لوحة مفاتيح…).","اخترت هاتفك (قرّبه من اللوحة ليصبح الأقوى) ويعرض الأمر <code>bytes</code> بنى AD الخاصة به: Flags، ثم بيانات المصنّع (Apple وSamsung وGoogle…).","يطبع <code>watch</code> سطرًا لكل حزمة من هاتفك، ويمكنك قراءة فترة الإعلان من الفواصل <code>+… ms</code>.","عند تفعيل <code>mode passive</code> تختفي ردود المسح (وبعض الأسماء)، ويعيدها <code>mode active</code>."],"learn":["الإعلان","القنوات 37 · 38 · 39","بنى AD","المسح النشط مقابل السلبي","RSSI ← المسافة","العناوين الخاصة","دورة عمل المسح"],"pins":{"0":{"role":"VCC"},"1":{"role":"BLK"},"2":{"role":"RES"},"3":{"role":"DC"},"4":{"role":"CS"},"5":{"role":"SDA"},"6":{"role":"SCL"},"7":{"role":"GND"},"8":{"role":"BTN"},"9":{"role":"BOOT"}},"commands":{"0":{"does":"يبني المختبر B1 ويرفع البرنامج إلى اللوحة. يحمّل أول بناء NimBLE-Arduino 2.5.1 (حزمة البلوتوث).","see":"<code>Hard resetting via RTS pin…</code>. تعرض الشاشة الرادار بخط يمسح الدائرة.","fix":"“Failed to connect”: اضغط BOOT مطوّلًا، ثم المس RST، ثم اترك BOOT، وشغّل الأمر مرة أخرى."},"1":{"does":"يفتح المراقب التسلسلي (تعيد اللوحة التشغيل).","see":"<code>ble-lab-b1: NimBLE 2.5.1 up, address …</code> و<code>+ active scan, 100/100 ms (100% listening)</code>، ثم قائمة الأوامر.","fix":"لا يظهر سطر <code>NimBLE … up</code>: لم تبدأ الحزمة؛ افصل اللوحة ثم أعد توصيلها."},"2":{"does":"يطبع كل جهاز سُمع خلال آخر 30 s، الأقوى أولًا: RSSI وتخمين المسافة والنوع والعنوان ونوعه والحزم والاسم أو الشركة المصنّعة.","see":"جدول مثل <code>1  -46  0.6  phone  5A:3C:…  private (RPA)  412  Apple</code>. من عشرة إلى خمسين صفًا في شقة، وأقل في بيت.","fix":"فارغ: هل البلوتوث يعمل حولك؟ الهواتف غالبًا لا تعلن إلا عندما تكون شاشتها مضاءة أو يطلب ذلك تطبيق."},"3":{"does":"يصبح هاتفك الجهاز الأقوى. افتح قفله: يعلن iPhone كثيرًا عندما تكون الشاشة مضاءة.","see":"على <b>الرادار</b> تتحرك نقطة إلى المركز؛ وفي <b>list</b> تقفز إلى الصف 1 بحوالي −40 dBm.","fix":"قد تبقى هواتف Android صامتة: افتح nRF Connect واستخدم تبويب Advertiser، أو فعّل Nearby Share / Quick Share لحظة."},"4":{"does":"يختار الصف 1 لعرض <b>inspect</b> ويطبع إعلانه ورد المسح، بنية بنية.","see":"<code>[02 01 | 1A] Flags</code> و<code>[0A FF | 4C 00 10 …] Manufacturer data</code> (Apple: Nearby info)، وربما <code>[02 0A | 0C] TX power</code>.","fix":"<code>no scan response</code>: بعض الأجهزة لا ترسل ردًّا؛ وفي الوضع السلبي لا أحد يطلبه."},"5":{"does":"يطبع سطرًا لكل حزمة من الجهاز المختار، مع الزمن منذ الحزمة السابقة.","see":"أسطر <code>&lt; +  182 ms  -47 dBm  31 B</code>. بعض الفواصل حزم فائتة (أرسلها هاتفك على قناة لا تستمع إليها اللوحة)؛ وأقصر فاصل متكرر هو فترته.","fix":"يوقفه <code>watch off</code>. إن كانت الأسطر كثيرة: ابدأ بـ <code>near -60</code>."},"6":{"does":"السلبي: تكتفي اللوحة بالاستماع. النشط: ترسل أيضًا طلب مسح إلى كل جهاز قابل للمسح، فتحصل على حزمة ثانية هي رد المسح.","see":"في الوضع السلبي يفقد عرض <b>inspect</b> صف <i>scan rsp</i> وتتحول بعض الأسماء إلى أسماء شركات مصنّعة. يعرض عرض air الوضع الحالي.","fix":""},"7":{"does":"استمع 30 ms من كل 100 (دورة عمل 30 %) بدل الاستماع طوال الوقت.","see":"ينخفض عدد الحزم في الثانية في عرض <b>air</b> إلى نحو الثلث. تمسح الهواتف بهذه الطريقة لتوفير البطارية. يعيدها <code>timing 100 100</code>.","fix":"يجب ألا تزيد النافذة عن الفترة."},"8":{"does":"يأخذ متوسط RSSI للجهاز المختار كمرجع عند 1 m لتخمين المسافات.","see":"<code>+ 1 m = -58 dBm now: distances use it</code>. ابتعد: ستنجرف النقطة إلى الخارج.","fix":"تقفز المسافات بمقدار ±1 m: هذا هو RSSI. الأجسام والجدران واتجاه الهاتف تغيّره بمقدار 5–10 dB."}},"panels":{"0":{"title":"مسار البلوتوث، من الاستماع إلى الاستضافة","intro":"ثمانية مختبرات، لكل منها برنامجه الثابت. تبدأ اللوحة مستمعًا خالصًا وتنتهي باستضافة لوحة مفاتيحك. اختر مختبرًا لترى دور اللوحة واتجاه تدفق البيانات؛ يشير القفل إلى المختبرات التي يهم فيها الاقتران والتشفير."},"1":{"title":"ثلاث قنوات، صيحات كثيرة","intro":"يقسم Bluetooth LE نطاق 2.4 GHz إلى 40 قناة عرض كل منها 2 MHz. يستخدم الإعلان ثلاثًا منها فقط: 37 و38 و39، وهي موضوعة في الفراغات بين قنوات Wi-Fi المعتادة 1 و6 و11. يرسل كل حدث إعلان الحزمة نفسها على القنوات الثلاث واحدة تلو الأخرى. يستمع الماسح إلى قناة واحدة في كل مرة: لا تُحتسب الحزمة إلا إذا وقعت داخل نافذة استماع على قناتها. حرّك شريط النافذة وراقب عدد الحزم التي تلتقطها اللوحة؛ وبدّل إلى النشط لترى طلب المسح والرد عليه."},"2":{"title":"حزمة إعلان واحدة، بايتًا بايتًا","intro":"ما يرسله الراديو فعلًا، من أول بت إلى المجموع الاختباري. اختر جهازًا، ثم تنقّل بين الحقول بـ ◀ ▶. بنى AD في المنتصف هي بالضبط ما يعرضه عرض <b>inspect</b> والأمر <code>bytes</code>."},"3":{"title":"ما تعرضه الشاشة","intro":"أربعة عروض. النقرة على زر الضغط (أو BOOT) تنتقل إلى العرض التالي، والنقر المزدوج ينفذ الإجراء المكتوب أسفل اليسار، والضغط المطوّل يوقف المسح مؤقتًا أو يستأنفه. الأيقونة أعلى اليمين هي الراديو: رادار يمسح أثناء المسح."}},"steps":["أبقِ الشاشة موصولة كما في الدرس 03 (زر الضغط اختياري). ارفع <code>ble-lab-b1</code> إلى اللوحة وافتح المراقب. <b>نقطة التحقق 1:</b> ظهور <code>NimBLE 2.5.1 up</code> والرادار يمسح.","اكتب <code>list</code>. <b>نقطة التحقق 2:</b> جدول أجهزة مع أنواعها؛ ابحث عن <i>audio</i> (يعلن جهاز JBL لديك من أجل تطبيقه) و<i>keyboard/mouse</i> وشركات Apple أو Microsoft.","ضع هاتفك المفتوح القفل بجانب اللوحة، ثم <code>pick 1</code>، وانقر للانتقال إلى <b>inspect</b>. <b>نقطة التحقق 3:</b> بايتاته في بنى AD ملونة، ونوع العنوان <i>private (RPA)</i>.","اكتب <code>watch</code> لعشر ثوانٍ، ثم <code>watch off</code>. <b>نقطة التحقق 4:</b> تستطيع ذكر فترة إعلان هاتفك.","جرّب <code>mode passive</code> / <code>mode active</code> و<code>timing 100 30</code> / <code>timing 100 100</code> وأنت تنظر إلى عرض <b>air</b>.","اختياري: شغّل <code>calib</code> والهاتف على بعد 1 m، ثم امشِ إلى الجهة الأخرى من الغرفة وراقب الرادار."],"note":"كل ما هنا هو ما تبثه الأجهزة لأي أحد؛ ولا تتصل اللوحة بها أبدًا. ومع ذلك فالقائمة هي أجهزة جيرانك: لا تنشر عناوينها (فهي لا تدخل في السجلات المحفوظة). تغيّر الهواتف عنوانها الخاص كل 15 دقيقة تقريبًا، فقد يظهر الهاتف نفسه مرتين. المسافات تخمينات من قوة الإشارة، ودقتها حتى ضعفين. يدعم ESP32-S3 Bluetooth LE فقط: البلوتوث الكلاسيكي (معظم بث الصوت ولوحات المفاتيح القديمة) غير مرئي له."}`),B2:JSON.parse(`{"title":"كن مرئيًا","heading":"اللوحة تصيح ببياناتها","goal":"في B1 كانت اللوحة تستمع. الآن تصبح <b>منارة</b> (beacon): تحزم قيمًا حية (ضغطات الزر ودرجة حرارة الشريحة ومدة التشغيل) في إعلانها الخاص ذي 31 بايتًا، فيستطيع أي هاتف قريب قراءتها <i>دون اتصال</i>. وتحمل الميزانية نفسها <b>iBeacon</b> أو <b>Eddystone-URL</b> أو اسمًا فقط. أنت تختار عدد مرات الصياح (الفترة) وشدته (قدرة TX)، وترى كم سيكلّف ذلك منارة تعمل ببطارية قرصية.","goalLine":"اجعل اللوحة تبث قيمًا حية يقرؤها هاتفك دون أن يتصل بها أبدًا.","goalCheck":["يعرض nRF Connect الجهاز <b>Bench B2</b> ويُظهر <b>Manufacturer data 0xFFFF</b> تتغير بايتاتها كل ثانية (مدة التشغيل) وعند النقر المزدوج (عدد الضغطات).","يعرض عرض <b>packet</b> ‏24 من 31 بايتًا في بنى ملونة، وتومض البايتات المتغيرة باللون الأبيض.","يظهر <code>mode ibeacon</code> كـ iBeacon على Android (لا ترى تطبيقات iPhone أجهزة iBeacon: هذا من iOS لا منك)، ويظهر <code>mode url</code> كـ Eddystone URL في nRF Connect.","مع <code>connectable off</code> و<code>scanresp off</code> يعرض عرض packet القيمة <b>ADV_NONCONN_IND</b>، ولا يعرض nRF Connect زر Connect بعد الآن، ولا يمكن أن تنخفض الفترة عن 100 ms.","تستطيع أن تشرح من عرض <b>budget</b> لماذا تعلن المنارات كل 500-1000 ms وليس كل 20."],"learn":["دور المذيع (broadcaster)","ميزانية 31 بايتًا","بنى AD","بيانات المصنّع","iBeacon وEddystone","ADV_IND · SCAN_IND · NONCONN","الفترة وadvDelay","قدرة TX مقابل البطارية"],"pins":{"0":{"role":"VCC"},"1":{"role":"BLK"},"2":{"role":"RES"},"3":{"role":"DC"},"4":{"role":"CS"},"5":{"role":"SDA"},"6":{"role":"SCL"},"7":{"role":"GND"},"8":{"role":"BTN"},"9":{"role":"BOOT"}},"commands":{"0":{"does":"يبني المختبر B2 ويرفع البرنامج إلى اللوحة.","see":"عرض <b>packet</b>: ‏<code>bench ADV_IND every 100 ms</code> وصفّان من الخلايا الملونة.","fix":"“Failed to connect”: اضغط BOOT مطوّلًا، ثم المس RST، ثم اترك BOOT، وشغّل الأمر مرة أخرى."},"1":{"does":"يفتح المراقب التسلسلي.","see":"<code>+ bench ADV_IND every 100 ms, 24+7 B</code> وقائمة الأوامر.","fix":""},"2":{"does":"الهاتف هو الماسح الآن (لا تستطيع لوحة واحدة سماع نفسها). النقر على الصف يفتح تفاصيل الإعلان.","see":"Complete Local Name ‏<code>Bench B2</code>، وManufacturer data ‏<code>0xFFFF 0x01…</code>؛ والبايتان الأخيران (مدة التشغيل) يتغيران كل ثانية. المس RAW لترى البايتات الـ 24 كلها.","fix":"غير ظاهر: اسحب للأسفل للتحديث؛ ثم <code>adv on</code>. على iPhone تظهر Manufacturer data كسلسلة سداسية عشرية واحدة: هي البايتات نفسها."},"3":{"does":"يحتسب ضغطة داخل الحزمة. تستبدل اللوحة بيانات الإعلان؛ ويرسل المتحكم البايتات الجديدة بدءًا من الحدث التالي.","see":"<code>- presses 1: in the next packet</code>؛ وفي عرض packet تومض خليتان باللون الأبيض؛ وفي nRF Connect يصبح البايت 4-5 من بيانات المصنّع <code>01 00</code>.","fix":""},"4":{"does":"يطبع الحزمتين، بنية بنية.","see":"<code>[02 01 | 06] Flags</code> و<code>[09 09 | 42 65 6E 63 68 20 42 32] Name</code> و<code>[0A FF | FF FF 01 01 00 2E 10 2C 01] Manufacturer data</code>.","fix":""},"5":{"does":"تخطيط Apple: ‏4C 00 02 15، ثم UUID من 16 بايتًا، ثم major وminor، ثم القدرة عند 1 m. ‏30 من 31 بايتًا: ينتقل الاسم إلى رد المسح.","see":"<code>+ ibeacon ADV_IND every 100 ms, 30+10 B</code>. في nRF Connect على Android: “iBeacon”، وUUID ‏BA5E0000-B1E5-…، وMajor 1، وMinor 2. وسيعرض B1 على لوحة أخرى نوع المنارة باللون البنفسجي.","fix":"لا يعرض iPhone شيئًا مميزًا، أو لا يعرض المنارة: يستبعد iOS إطارات iBeacon من مسح كل تطبيق. لا يراها إلا Core Location (مراقبة المناطق)."},"6":{"does":"Eddystone-URL: بيانات الخدمة FEAA مع عنوان URL مضغوط (‏https:// = بايت واحد، و.com/ = بايت واحد).","see":"يعرض nRF Connect العنوان <b>Eddystone URL</b> ‏https://github.com/. عنوان URL طويل جدًا: <code>x the URL doesn't fit…</code>، ويبقى القديم.","fix":"كان Android يعرض هذه كإشعارات منبثقة (Physical Web)؛ توقف ذلك منذ 2018. ما زالت التطبيقات تفك ترميزها."},"7":{"does":"أولًا ADV_SCAN_IND (يمكن مسحه لكن لا الاتصال به)، ثم ADV_NONCONN_IND: بث خالص لا يجيب أحدًا.","see":"يتغير عنوان عرض packet؛ ويختفي زر Connect في nRF Connect؛ ويفرغ صف رد المسح.","fix":"رُفعت قيمة <code>interval</code> إلى 100 ms: الحد الأدنى للإعلانات غير القابلة للاتصال (قاعدة Bluetooth 4.x؛ يسمح 5.0 بـ 20، وتبقى المنارات عند 100 وأكثر)."},"8":{"does":"عدد مرات صياح اللوحة. انتقل إلى عرضي <b>air</b> و<b>budget</b> لترى كلًّا منهما.","see":"<code>+ … every 1000 ms</code>؛ يتحدث عمود الفترة في nRF Connect (Android) أو رسم RSSI أبطأ؛ وتقفز مدة عمر البطارية القرصية في عرض budget من أسابيع إلى سنوات.","fix":"<code>interval 20</code> مرفوض مع connectable off: فعّل connectable أولًا."},"9":{"does":"قدرة TX بوحدة dBm (أمر مدمج في الصدفة). كلما انخفضت قصر المدى وقل التيار.","see":"ينخفض RSSI في nRF Connect بحوالي 20 dB عند المسافة نفسها؛ ويتغير أيضًا حقل قدرة TX في وضع الاسم.","fix":""},"10":{"does":"يوقف الإعلان. تصبح اللوحة غير مرئية.","see":"<code>- advertising off: the board is invisible</code>؛ يُظهره nRF Connect بلون رمادي بعد بضع ثوانٍ.","fix":""}},"panels":{"0":{"title":"ابنِ إعلانًا","intro":"كل حقل تضيفه يكلّف بياناته زائد بايتين (الطول والنوع). ضع كل حقل في الإعلان، أو في رد المسح (يُرسل فقط عندما يطلبه ماسح)، أو اتركه خارجًا، وراقب امتلاء ميزانية 31 بايتًا. أوضاع اللوحة الأربعة إعدادات جاهزة."},"1":{"title":"متى يسمعه الماسح؟","intro":"ترسل اللوحة كل حدث إعلان على القنوات 37 و38 و39 على التوالي، كل فترة زائد تأخير عشوائي 0-10 ms. يستمع الهاتف إلى قناة واحدة في كل مرة، خلال نافذة من كل فترة مسح. حرّك الأرقام وعدّ ما يُلتقط. أوقف التأخير العشوائي لترى سبب وجوده."},"2":{"title":"ما تعرضه الشاشة","intro":"أربعة عروض. النقرة تنتقل إلى العرض التالي؛ والنقر المزدوج في أي مكان يحتسب ضغطة داخل الحزمة؛ والضغط المطوّل يشغّل الإعلان أو يوقفه."}},"steps":["التوصيل نفسه كما في B1. ارفع <code>ble-lab-b2</code> إلى اللوحة وافتح المراقب. <b>نقطة التحقق 1:</b> ‏<code>bench ADV_IND every 100 ms, 24+7 B</code>.","ثبّت nRF Connect (أو LightBlue) على هاتفك واعثر على <b>Bench B2</b>؛ افتحه بالنقر ولا تتصل. <b>نقطة التحقق 2:</b> ‏Manufacturer data ‏0xFFFF مع بايتات تتغير كل ثانية.","انقر زر اللوحة نقرًا مزدوجًا عدة مرات. <b>نقطة التحقق 3:</b> يتغير عداد الضغطات على الهاتف دون أي اتصال.","جرّب <code>mode ibeacon</code> (يعرضه Android) و<code>mode url</code>. قارن مع أداة البناء أعلاه: أي الحقول انتقلت إلى رد المسح، ولماذا؟","<code>connectable off</code> و<code>scanresp off</code>. <b>نقطة التحقق 4:</b> ‏ADV_NONCONN_IND، ولا يوجد زر Connect على الهاتف.","انتقل إلى عرضي <b>air</b> و<b>budget</b>، ثم جرّب <code>interval 1000</code> و<code>power -12</code>. <b>نقطة التحقق 5:</b> تستطيع أن تقول ما يكلّفه كل منهما وما يمنحه."],"note":"يستطيع أي شخص قريب قراءة ما تبثه اللوحة: لا تضع أي شيء خاص في إعلان. ‏0xFFFF هو معرّف الشركة الذي تحجزه Bluetooth SIG للاختبارات، مناسب على طاولة التجارب وليس لمنتج. لا ترى تطبيقات iPhone إطارات iBeacon إطلاقًا (يزيلها iOS من عمليات المسح)، لذا اختبر هذا الوضع على Android أو بتشغيل B1 على لوحة ثانية. عرض budget تقدير لشريحة منارة قرصية نموذجية وفق افتراضاتها المذكورة: أما لوحة ESP32-S3 هذه فتسحب نحو 80 mA والشاشة تعمل، وهذا أكثر بكثير مما تتحمله بطارية قرصية. لا يستطيع الراديو الواحد سماع نفسه، فالهاتف هو الماسح في هذا المختبر."}`),B3:{title:`اتصل وتحدث`,heading:`هاتفك يتصل ويقرأ ويكتب`,goal:`الإعلان صياح؛ أما <b>الاتصال</b> فحديث خاص. يتصل الهاتف (<i>central</i>) باللوحة (<i>peripheral</i>)، ومن ثم يلتقيان على إيقاع ثابت هو فترة الاتصال، ويقفزان عبر 37 قناة بيانات. على اللوحة قاعدة بيانات صغيرة هي جدول <b>GATT</b>: خدمة Bench مع LED وMessage وButton وTemperature وUptime. من nRF Connect أو LightBlue تكتب لون LED، وتضع رسالة على الشاشة، وتقرأ درجة حرارة الشريحة، وتشترك في الزر.`,goalLine:`تحكّم باللوحة من هاتفك عبر البلوتوث، وشاهد وصول كل عملية في عرض gatt.`,goalCheck:[`يعرض nRF Connect (أو LightBlue) الجهاز <b>Bench B3</b>، ويتصل به، ويسرد خدمة Bench بخمس خصائص مسمّاة إضافة إلى Device Information وBattery.`,`كتابة <code>FF5000</code> في <b>LED</b> تجعل LED المدمج برتقاليًا، ويومض صف LED باللون الأزرق في عرض gatt.`,`كتابة نص في <b>Message</b> تعرضه بحجم كبير في عرض message.`,`بعد الاشتراك في <b>Button</b>، تصل كل نقرة على اللوحة إلى الهاتف كإشعار؛ وترسل Temperature إشعارًا كل 2 s.`,`يعرض عرض <b>link</b> فترة الاتصال وMTU وRSSI، ويغيّر <code>params slow</code> الفترة بشكل ملحوظ.`],learn:[`central وperipheral`,`GATT: الخدمات والخصائص`,`UUIDs (‏16 و128 بت)`,`قراءة · كتابة · إشعار`,`CCCD (الاشتراك)`,`MTU`,`فترة الاتصال`],pins:{0:{role:`VCC`},1:{role:`BLK`},2:{role:`RES`},3:{role:`DC`},4:{role:`CS`},5:{role:`SDA`},6:{role:`SCL`},7:{role:`GND`},8:{role:`BTN`},9:{role:`BOOT`}},commands:{0:{does:`يبني المختبر B3 ويرفع البرنامج إلى اللوحة.`,see:`عرض <b>gatt</b> بخمسة صفوف؛ وتُظهر أيقونة الراديو حلقات: الإعلان جارٍ.`,fix:`“Failed to connect”: اضغط BOOT مطوّلًا، ثم المس RST، ثم اترك BOOT، وشغّل الأمر مرة أخرى.`},1:{does:`يفتح المراقب التسلسلي.`,see:`<code>- advertising as "Bench B3"</code>، ثم قائمة الأوامر.`,fix:``},2:{does:`يتصل هاتفك. ثبّت nRF Connect for Mobile (من Nordic، مجاني؛ لـ iPhone وAndroid) أو LightBlue. على iPhone لا تتصل أبدًا من Settings → Bluetooth: التطبيقات هي التي تفعل ذلك.`,see:`المراقب: ‏<code>+ connected: 5A:3C:…</code> و<code>- interval 30.00 ms …</code>، وبعد قليل <code>- MTU 255: 252 bytes of data per packet</code>. تتحول أيقونة الراديو إلى حلقتين، ويثبت LED على اللون الأزرق.`,fix:`Bench B3 غير ظاهر: مرّر القائمة، أو صفّ بالاسم “Bench”. ما زال لا شيء: <code>adv on</code>.`},3:{does:`يكتب 3 بايتات: أحمر FF، أخضر 50، أزرق 00.`,see:`<code>&lt; write LED FF 50 00</code>؛ يتوهج LED المدمج بالبرتقالي؛ ويومض صف LED بالأزرق ويعرض عينة اللون.`,fix:`<code>LED wants 3 bytes, got 1</code>: اختر Byte Array، وليس Text أو UINT8.`},4:{does:`يكتب نص UTF-8 (حتى 40 بايتًا).`,see:`<code>&lt; write Message "hello bench"</code>؛ انتقل إلى عرض <b>message</b>: نص كبير، “written 3s ago”.`,fix:`تظهر الحروف المشكولة كمربعات: خط الشاشة ASCII عادي.`},5:{does:`الاشتراك يكتب 01 00 في CCCD الخاص بالزر. ثم يدفع كل إيماءة قيمة من 3 بايتات: الإيماءة والعدد (بايتان).`,see:`<code>&lt; subscribe Button (CCCD = 1)</code>، ثم مع كل نقرة <code>&gt; notify Button: click #3</code>؛ ويعرض الهاتف <code>01-03-00</code>. يظهر جرس على صف Button.`,fix:`<code>(nobody subscribed)</code> في المراقب: اشترك أولًا.`},6:{does:`يقرأ بايتين (°C × 100، little-endian). يخبر الواصف 2904 التطبيقات كيف تعرضها.`,see:`يعرض nRF Connect القيمة <code>41.42 °C</code> (الخام <code>2E-10</code>)؛ وعند الاشتراك تتحدث كل 2 s.`,fix:``},7:{does:`يطلب من الهاتف فترة 100-200 ms (والسماح للوحة بتخطي 4 أحداث)، ثم 15-30 ms. الهاتف هو من يقرر.`,see:`<code>- new params: 112.50 ms, latency 4</code>؛ تبطؤ النقطة في عرض <b>link</b>. تصل الإشعارات الآن على دفعات.`,fix:`رُفض <code>params</code> أو تم تجاهله: ترفض هواتف iPhone بعض القيم؛ حاول مرة أخرى بعد بضع ثوانٍ.`},8:{does:`ينهي الاتصال. تعلن اللوحة من جديد من تلقاء نفسها.`,see:`<code>! disconnected 0x16: we hung up</code>؛ يحتفظ عرض link بالسبب.`,fix:``}},panels:{0:{title:`من الإعلان إلى المحادثة، خطوة بخطوة`,intro:`ما يحدث عند النقر على Connect في nRF Connect، وعند كتابة LED أو عندما ترسل اللوحة إشعار نقرة. تعرض كل خطوة بايتات ATT الحقيقية: البايت الأول رمز العملية، والبايتان التاليان المقبض (رقم الصف في جدول اللوحة)، والباقي القيمة.`},1:{title:`خدمة Bench، مباشرة`,intro:`جدول GATT الخاص باللوحة كما يعرضه nRF Connect. اضغط عملية لإرسالها: تعبر الحزمة، ويضيء صف اللوحة كما في عرض gatt، وتُفك ترميز البايتات في الأسفل.`},2:{title:`ما تعرضه الشاشة`,intro:`أربعة عروض. النقرة تنتقل إلى العرض التالي؛ وكل إيماءة (نقرة، نقر مزدوج، ضغط مطوّل) تُرسل أيضًا إلى الهاتف المشترك كإشعار Button. النقر المزدوج في عرضي gatt وmessage يرسل نقرة إضافية.`}},steps:[`التوصيل نفسه كما في B1. ارفع <code>ble-lab-b3</code> إلى اللوحة وافتح المراقب. <b>نقطة التحقق 1:</b> ‏<code>advertising as "Bench B3"</code>.`,`على هاتفك، ثبّت nRF Connect (أو LightBlue)، واعثر على <b>Bench B3</b> واتصل به. <b>نقطة التحقق 2:</b> ‏<code>connected</code> في المراقب، وخدمة Bench مع LED وMessage وButton وTemperature وUptime على الهاتف.`,`اكتب <code>FF5000</code> في LED ونصًا في Message. <b>نقطة التحقق 3:</b> LED برتقالي، والرسالة على الشاشة.`,`اشترك في Button وTemperature، ثم انقر زر اللوحة. <b>نقطة التحقق 4:</b> تصل القيم إلى الهاتف؛ وتظهر أجراس في عرض gatt.`,`انتقل إلى عرض <b>link</b> وجرّب <code>params slow</code> / <code>params fast</code> و<code>phy 2m</code>. <b>نقطة التحقق 5:</b> تتغير الفترة على الشاشة.`,`اكتب <code>led auto</code> لتعيد LED إلى حالة الراديو، ثم <code>disconnect</code>.`],note:`يستطيع أي شخص قريب الاتصال بـ Bench B3 وتغيير LED: لا يوجد اقتران بعد، وكل شيء يسافر كنص صريح. هذا ما يفعله B4. تخزّن هواتف iPhone جدول GATT لجهاز ما مؤقتًا: إن غيّر مختبر لاحق الجدول وعرض iPhone صفوفًا قديمة، أطفئ البلوتوث ثم شغّله. يملك ESP32-S3 راديو واحدًا: لا يستخدم B3 شبكة Wi-Fi، فلا قلق من التعايش بينهما.`},B4:JSON.parse(`{"title":"اقترن وثق","heading":"اجعل الاتصال خاصًا، وتذكّر من يُسمح له","goal":"في B3 كان بإمكان أي شخص قريب الاتصال وقراءة كل بايت. يضيف B4 خاصية <b>Vault</b> لا تقدمها اللوحة إلا عبر اتصال <b>مشفّر وموثّق</b>. المسها من الهاتف يبدأ <b>الاقتران</b>: يظهر رمز المرور بحجم كبير على شاشة TFT، أو تعرض الشاشتان الأرقام الستة نفسها وتؤكدها بالزر. بعد ذلك <b>تربط</b> اللوحة (bond): تحتفظ بالمفاتيح في الذاكرة flash، وتتعرف على هاتفك خلف عنوانه الخاص المتغير، ويمكنها رفض كل من سواه.","goalLine":"اقرن هاتفك بالطرق الثلاث، واقرأ Vault، واقفل اللوحة على هاتفك.","goalCheck":["مع <code>pair passkey</code> تؤدي قراءة Vault على الهاتف إلى ظهور نافذة لإدخال رمز، وتعرض شاشة TFT ستة أرقام، وبعد كتابتها يقرأ الهاتف <b>the bench's secret: 42</b>.","يمتلئ عرض <b>ceremony</b> مرحلة بعد مرحلة حتى <b>bonded</b>، ويُظهر الرأس قفلًا بنفسجيًا ومفتاحًا كهرمانيًا.","مع <code>pair justworks</code> (بعد <code>forget all</code> ونسيان اللوحة على الهاتف) يكون الاتصال مشفّرًا لكن Vault يبقى مرفوضًا: تستطيع أن تشرح السبب.","مع <code>pair compare</code> تقبل الأرقام المتطابقة بنقرة على اللوحة ولمسة على الهاتف.","بعد <code>allow bonded</code> يبقى هاتفك قادرًا على الاتصال، ولا يستطيع ذلك هاتف ثانٍ (أو الهاتف نفسه بعد نسيان اللوحة)."],"learn":["الاقتران مقابل الربط (pairing vs bonding)","قدرات الإدخال والإخراج (IO capabilities)","Just Works · Passkey · Numeric Comparison","LE Secure Connections (ECDH)","الحماية من MITM","LTK وIRK","العناوين الخاصة","قائمة القبول (filter accept list)"],"pins":{"0":{"role":"VCC"},"1":{"role":"BLK"},"2":{"role":"RES"},"3":{"role":"DC"},"4":{"role":"CS"},"5":{"role":"SDA"},"6":{"role":"SCL"},"7":{"role":"GND"},"8":{"role":"BTN"},"9":{"role":"BOOT"}},"commands":{"0":{"does":"يبني المختبر B4 ويرفع البرنامج إلى اللوحة.","see":"عرض <b>ceremony</b>: “Waiting for a phone to connect...” وثماني مراحل رمادية.","fix":"“Failed to connect”: اضغط BOOT مطوّلًا، ثم المس RST، ثم اترك BOOT، وشغّل الأمر مرة أخرى."},"1":{"does":"يفتح المراقب التسلسلي.","see":"<code>- pairing: Passkey · lock off · anyone may connect</code>، ثم قائمة الأوامر. تُحفظ الطريقة في الذاكرة flash: وتبقى بعد إعادة رفع B4.","fix":""},"2":{"does":"يرفض Vault الاتصال النصي الصريح برسالة “Insufficient Authentication”؛ فيرد الهاتف ببدء الاقتران.","see":"يطلب الهاتف رمزًا؛ وتعرض شاشة TFT العبارة <b>PASSKEY ENTRY</b> وستة أرقام؛ ويطبع المراقب <code>! passkey 482915: type it on the other device</code>. تمتلئ المراحل 1-5 في عرض ceremony، وتنبض “check” بالكهرماني.","fix":"لا توجد نافذة على iPhone: اقرأ Vault مرة أخرى. وعلى Android قد تكون النافذة إشعارًا."},"3":{"does":"يتحقق الطرفان من رمز المرور بتًّا بتًّا (20 جولة من القيم المؤكدة والعشوائية)، ثم يشفّران ويتبادلان المفاتيح.","see":"<code>+ secured: authenticated, bonded, key 16 B</code> و<code>- identity: 4C:…</code>؛ ويقرأ الهاتف <b>the bench's secret: 42</b>. أيقونتا القفل والمفتاح في الرأس؛ ويكتمل مسار ceremony.","fix":"<code>x … confirm failed: wrong passkey</code>: خطأ في الكتابة. اقرأ Vault مرة أخرى للحصول على رمز جديد."},"4":{"does":"الهاتف المربوط يملك المفاتيح: لا مراسم، ويبدأ التشفير فورًا.","see":"يعرض عرض ceremony العبارة <b>stored keys: bonded before, no ceremony</b> ويقفز من الاتصال إلى التشفير.","fix":""},"5":{"does":"يسرد الأجهزة المربوطة بعنوان الهوية (يحوّل IRK عنوان الهاتف الخاص إليه).","see":"<code>1 bonded device …</code> و<code>1  4C:…  random static</code> (يستخدم iPhone ومعظم أجهزة Android هوية عشوائية ثابتة). يعلّمه عرض <b>bonds</b> بـ “&lt;- here”.","fix":""},"6":{"does":"يحذف الروابط على اللوحة. ما زال الهاتف يحتفظ بنصفه: انسَ الجهاز في Settings → Bluetooth (على iPhone: ⓘ ← Forget This Device؛ على Android: الترس ← Unpair؛ على macOS: نقرة يمنى ← Forget).","see":"<code>! forgot every bond</code> و<code>- now forget \\"Bench B4\\" on the phone too</code>. إن تخطيت خطوة الهاتف: <code>x ENC_CHANGE failed 0x206: key missing: one side forgot the bond</code>.","fix":""},"7":{"does":"تقول اللوحة الآن “لا إدخال ولا إخراج”: لا أحد يستطيع التحقق من شيء. يُشفَّر الاتصال لكنه لا يُوثَّق.","see":"<code>+ secured: Just Works, bonded</code>، وقفل بنفسجي، لكن قراءة Vault تفشل مجددًا بـ Insufficient Authentication: يشترط Vault الحماية من MITM.","fix":"هذا هو الدرس: Just Works يمنع المتنصتين، لا الرجل الذي في المنتصف."},"8":{"does":"تعرض الشاشتان الأرقام الستة نفسها. نقرة على اللوحة تعني نعم، وضغطة مطوّلة تعني لا؛ وللهاتف زره الخاص.","see":"<b>NUMERIC COMPARISON</b> على TFT، والرقم نفسه على الهاتف؛ وبعد الموافقتين: <code>+ secured: authenticated, bonded</code>.","fix":"الضغط المطوّل (لا) ينتهي بـ <code>numbers didn't match: said no</code>."},"9":{"does":"لا تدخل قائمة القبول إلا هويات الأجهزة المربوطة؛ يحلّ المتحكم كل عنوان خاص بمفاتيح IRK المخزنة ويرفض الباقي.","see":"<code>+ only bonded phones may connect (saved)</code>. يتصل هاتفك؛ أما هاتف آخر (أو هاتفك بعد نسيان اللوحة) فلا يحصل على أي اتصال.","fix":"إن حبست نفسك خارجًا: <code>allow anyone</code> عبر المنفذ التسلسلي."},"10":{"does":"يحتاج LED وMessage أيضًا إلى اتصال مشفّر. الأذونات جزء من جدول GATT الذي يُبنى مرة واحدة عند بدء التشغيل، لذا تحفظ اللوحة الإعداد وتعيد التشغيل.","see":"<code>lock on saved. … the board restarts now...</code>؛ وبعدها تؤدي كتابة LED من هاتف غير مقترن إلى بدء الاقتران أيضًا.","fix":"يعرض iPhone أذونات قديمة: أطفئ البلوتوث ثم شغّله (فهو يخزّن الجدول مؤقتًا)."}},"panels":{"0":{"title":"أي طريقة اقتران؟ تعتمد على الطرفين","intro":"في بداية الاقتران يذكر كل طرف ما يستطيع فعله: عرض رقم، أو كتابة رقم، أو ضغط نعم أو لا، أو لا شيء إطلاقًا. تحدد الإجابتان الطريقة. اختر قدرات الهاتف واللوحة (قدرات اللوحة هي ما يضبطه <code>pair</code>) وانظر من يعرض ومن يكتب."},"1":{"title":"اقتران واحد، حزمة بحزمة","intro":"رسائل Security Manager Protocol ‏(SMP) التي تعبر الهواء عندما يقرأ الهاتف Vault، ببايتاتها الحقيقية. تختلف كل طريقة في المنتصف فقط: كيف يثبت الشخص أن لا أحد يقف بينهما."},"2":{"title":"ما تعرضه الشاشة","intro":"خمسة عروض. النقرة تنتقل إلى العرض التالي؛ والنقر المزدوج ينفذ الإجراء في التذييل (secure وbonds وpress). وبينما تنتظر الأرقام المقارنة، يجيب الزر بدلًا من ذلك: نقرة = نعم، ضغط مطوّل = لا."}},"steps":["التوصيل نفسه كما في B3. ارفع <code>ble-lab-b4</code> إلى اللوحة وافتح المراقب. <b>نقطة التحقق 1:</b> ‏<code>pairing: Passkey</code> في أسطر بدء التشغيل.","اتصل من nRF Connect واقرأ <b>Vault</b>. اكتب الأرقام الستة من TFT. <b>نقطة التحقق 2:</b> يقرأ الهاتف السر؛ ويكتمل عرض ceremony؛ ويظهر القفل والمفتاح في الرأس.","اقطع الاتصال ثم أعده. <b>نقطة التحقق 3:</b> “stored keys”: لا رمز مرور هذه المرة.","نفّذ <code>forget all</code> وانسَ اللوحة على الهاتف. ثم <code>pair justworks</code> واقرأ Vault. <b>نقطة التحقق 4:</b> مشفّر، ومع ذلك مرفوض. لماذا؟","انسَ على الطرفين مرة أخرى، ثم <code>pair compare</code>، واقرأ Vault وانقر للتأكيد. <b>نقطة التحقق 5:</b> موثّق ومربوط.","<code>allow bonded</code>. <b>نقطة التحقق 6:</b> يتصل هاتفك؛ وبعد نسيانه على الهاتف لا يستطيع. أنهِ بـ <code>allow anyone</code>."],"note":"للاقتران نصفان: كلما نفّذت <code>forget</code> على اللوحة، انسَ اللوحة على الهاتف أيضًا (iPhone: Settings → Bluetooth → ⓘ → Forget This Device؛ Android: Bluetooth → الترس → Unpair؛ macOS: System Settings → Bluetooth → نقرة يمنى → Forget)، وإلا فسيفشل الاتصال التالي برسالة “key missing”. وإن نسي الهاتف وحده، يقبل NimBLE الاقتران الجديد ويستبدل الربط القديم من تلقاء نفسه (repeat pairing). تُحفظ إعدادات الطريقة والقفل وallow في الذاكرة flash (مساحة الاسم b4) وتبقى بعد إعادة التشغيل. لا يبلّغ NimBLE عن مراحل الميزات والطريقة وتبادل المفاتيح واحدة واحدة: يرسمها عرض ceremony كمراحل مستنتجة (حلقة) عندما تثبت مرحلة لاحقة أنها حدثت. تأتي اللوحة بالسر “the bench's secret: 42”؛ ويغيّره <code>vault &lt;text&gt;</code> حتى إعادة التشغيل التالية."}`),B5:JSON.parse(`{"title":"تطبيق الهاتف","heading":"تطبيقك الخاص، مباشرة إلى اللوحة","goal":"nRF Connect مفك براغي؛ والآن تصنع الأداة بنفسك. <b>esp-labs/apps/ble-app</b> تطبيق React صغير يستخدم <b>Web Bluetooth</b>: يصبح المتصفح نفسه عميل GATT، فتتحدث صفحة ويب على جهاز Mac أو هاتفك مع اللوحة دون Wi-Fi ودون خادم ودون متجر تطبيقات. يحتفظ البرنامج الثابت بخدمة Bench من B3 ويضيف أربع خصائص: <b>Canvas</b> ترسم عليها من الهاتف، و<b>Sensors</b> تبثّ خمس مرات في الثانية، واختبار <b>Speed</b> يدفع الإشعارات بأسرع ما يسمح به الراديو، وعناصر تحكم <b>Link</b> لتغيير الاتصال وأنت تراقب السرعة تتحرك.","goalLine":"تحكّم باللوحة وارسم عليها من صفحة ويب، وقِس كم بايتًا في الثانية يحمله اتصالك فعلًا.","goalCheck":["يسرد تبويب Connect في التطبيق خدمة Bench مع LED … Uptime إضافة إلى Canvas وSensors وSpeed وLink (‏ba5e0010-0013)، ويعرض سجل البايتات فيه كل عملية.","يظهر الخط المرسوم في تبويب Sketch على عرض <b>sketch</b> في اللوحة خلال جزء من الثانية.","يرسم تبويب Live أربعة خطوط؛ ولمس سلك توصيل على GPIO 1 يجعل خط اللمس يقفز.","ينتهي اختبار سرعة بحجم 50 kB بقيمة kB/s في التطبيق، والتشغيل نفسه كعمود في عرض <b>speed</b> على اللوحة؛ وبعد <b>Fast interval</b> أو <b>2M PHY</b> يكون التشغيل التالي أسرع بوضوح (أو تستطيع أن تقول لماذا لا)."],"learn":["Web Bluetooth","عميل GATT بلغة JavaScript","الكتابة دون استجابة (write without response)","البروتوكولات الثنائية","تدفقات الإشعارات","الإنتاجية = MTU × الحزم ÷ الفترة","2M PHY والحزم الطويلة"],"pins":{"0":{"role":"VCC"},"1":{"role":"BLK"},"2":{"role":"RES"},"3":{"role":"DC"},"4":{"role":"CS"},"5":{"role":"SDA"},"6":{"role":"SCL"},"7":{"role":"GND"},"8":{"role":"BTN"},"9":{"role":"BOOT"}},"commands":{"0":{"does":"يبني المختبر B5 ويرفع البرنامج إلى اللوحة.","see":"عرض <b>sketch</b>: “Open the ble-app, connect”. تُظهر أيقونة الراديو حلقات: الإعلان باسم <b>Bench B5</b>.","fix":"“Failed to connect”: اضغط BOOT مطوّلًا، ثم المس RST، ثم اترك BOOT، وشغّل الأمر مرة أخرى."},"1":{"does":"يثبّت التطبيق مرة واحدة (React وVite وTypeScript بإصدارات محددة) ويقدّمه على <code>http://localhost:5177</code>. لا توجد شيفرة خادم: يكتفي Vite بتسليم الصفحة إلى المتصفح.","see":"<code>➜ Local: http://localhost:5177/</code>","fix":"المنفذ مشغول: يعمل تطبيق مختبر آخر؛ أوقفه أو استخدم <code>pnpm dev --port 5178</code>."},"2":{"does":"تفتح نافذة اختيار الأجهزة الخاصة بالمتصفح (لا تستطيع الصفحة الاتصال بنفسها أبدًا). تسرد اللوحات التي لديها خدمة Bench، والأسماء التي تبدأ بـ “Bench”، أو أجهزة BLE-MIDI.","see":"اختر <b>Bench B5</b>. يعرض تبويب Connect مستكشف GATT؛ ويطبع المراقب <code>+ connected: …</code>. في المرة الأولى يطلب macOS السماح لـ Chrome باستخدام البلوتوث.","fix":"“Web Bluetooth isn't available here”: استخدم Chrome أو Edge، واستخدم localhost (وليس 127.0.0.1 أو عنوان IP الخاص بجهاز Mac)."},"3":{"does":"كل حركة تكتب 3 بايتات في LED (بمعدل كتابة واحدة كل 80 ms)؛ ويكتب Send حتى 40 بايتًا من UTF-8 في Message.","see":"يتبع LED إصبعك؛ وأسطر <code>&lt; write LED 1F 5C 99</code> في المراقب وحزم زرقاء تعبر شريط الهواء في التطبيق.","fix":"يبقى LED ثابتًا بعد <code>led auto</code>: حرّك العجلة مرة أخرى، فتستعيد اللوحة LED."},"4":{"does":"تذهب الخطوط إلى Canvas (‏ba5e0010) كـ <b>كتابات دون استجابة</b>: ‏<code>02 cc cc w n</code> + 3 بايتات لكل نقطة، كل 50 ms. تضعها اللوحة في طابور مهمة NimBLE وترسمها في loop().","see":"الخطوط نفسها في عرض <b>sketch</b> على اللوحة؛ وفي الأسفل <code>412 cmds 96 writes 9120 B</code>.","fix":"<code>DROPPED</code> على اللوحة: رسمت أسرع من 16 كتابة في الطابور؛ لا شيء ينكسر، وبضعة خطوط ناقصة. <code>sketch: a command was cut off</code>: رجع التطبيق إلى كتابات من 20 بايتًا (MTU 23)."},"5":{"does":"يشترك في Sensors: ‏12 بايتًا كل 200 ms (درجة الحرارة واللمس وذاكرة heap الحرة وRSSI ورقم تسلسلي).","see":"أربعة خطوط متحركة في التطبيق والخطوط المصغّرة الأربعة نفسها في عرض <b>live</b> على اللوحة؛ “notifying the app: 230 sent”. لمس الطرف الحر للسلك يجعل قيمة اللمس تقفز بآلاف.","fix":"خط اللمس مسطّح: لا سلك على GPIO 1؛ يصلح أي سلك توصيل، والطرف المعدني العاري هو الحساس."},"6":{"does":"يشترك في Speed ويكتب <code>01 50 C3 00 00</code>. تبثّ مهمة صغيرة على اللوحة 50,000 بايت في حزم من (MTU − 3) بايتًا حتى تمتلئ مخازن الحزمة، ثم تنتظر وتتابع؛ وبعدها ملخص من 15 بايتًا.","see":"المراقب: ‏<code>&lt; write Speed: start 50000 bytes</code> ثم <code>+ speed: 50000 B in 2310 ms = 21.6 kB/s</code>. يعرض التطبيق عمودًا بالرتبة نفسها.","fix":"<code>speed: subscribe to Speed (ba5e0012) first</code>: افتح تبويب Speed مرة قبل التشغيل من المنفذ التسلسلي."},"7":{"does":"يكتب 1 و3 و5 في Link: تطلب اللوحة من central فترة 7.5–15 ms، وPHY بسرعة 2M، وحزم راديو من 251 بايتًا.","see":"<code>- new params: 15.00 ms …</code> و<code>- PHY now 2M / 2M</code>؛ والتشغيل التالي أسرع. يحتفظ عرض <b>speed</b> في اللوحة بعمود لكل تشغيل مع MTU والفترة وPHY.","fix":"لا تغيير: central هو من يقرر. غالبًا ما يبقي macOS على 15 ms ويسمح بـ 2M؛ وبعض الهواتف ترفض 7.5 ms أو 2M. هذا هو الدرس: لا يستطيع peripheral إلا أن يطلب."},"8":{"does":"يمنح نفق cloudflared السريع التطبيق عنوانًا <code>https://…trycloudflare.com</code>، لأن الهواتف لا تسمح بـ Web Bluetooth إلا على https.","see":"Android: يفتحه Chrome وتظهر نافذة الاختيار نفسها. iPhone: افتحه في متصفح <b>Bluefy</b> المجاني (لا يدعم Safari ميزة Web Bluetooth).","fix":"يقول Bluefy إن الصفحة غير آمنة: استخدم عنوان https وليس http."}},"panels":{"0":{"title":"تغيير لون واحد، من JavaScript إلى LED","intro":"ما يحدث بين <code>navigator.bluetooth.requestDevice()</code> في التطبيق وتغيّر لون LED، وكيف يجد الإشعار طريقه عائدًا إلى رسم بياني. تعرض كل خطوة الاستدعاء الحقيقي أو البايتات الحقيقية في الهواء. اختر مسارًا، ثم تنقّل بـ ◀ ▶."},"1":{"title":"ما أقصى سرعة ممكنة؟","intro":"تحدد أربعة أرقام الإنتاجية: كم يبلغ حجم كل حزمة (MTU)، وكم مرة يلتقي الراديوان (فترة الاتصال)، وكم حزمة تتسع في اللقاء الواحد، وبأي سرعة تطير البتات (PHY). حرّك الأشرطة: يعرض الخط الزمني ثلاثة أحداث اتصال مع رسم كل حزمة بمقياس، والنتيجة هي الصيغة نفسها التي يقيسها تبويب Speed."},"2":{"title":"ما تعرضه الشاشة","intro":"ستة عروض. انقر للانتقال إلى التالي؛ والنقر المزدوج على sketch يمسحه، وعلى speed يبدأ تشغيلًا بحجم 50 kB، وعلى gatt يرسل نقرة Button. وتصل كل إيماءة أيضًا إلى التطبيق كإشعار Button، كما في B3."}},"steps":["التوصيل نفسه كما في B1 (الشاشة، والزر اختياري). اختياري: سلك توصيل واحد في GPIO 1 وطرفه الحر سائب: حساس اللمس لديك.","ارفع <code>ble-lab-b5</code> إلى اللوحة. <b>نقطة التحقق 1:</b> عرض sketch وحلقات الإعلان.","شغّل التطبيق (<code>pnpm install</code> مرة واحدة، ثم <code>pnpm dev</code>)، وافتح <code>http://localhost:5177</code> في Chrome واتصل بـ Bench B5. <b>نقطة التحقق 2:</b> يسرد مستكشف GATT تسع خصائص من Bench.","عجلة الألوان، ثم الرسالة، ثم ارسم شيئًا في Sketch. <b>نقطة التحقق 3:</b> رسمك على اللوحة.","افتح Live والمس السلك. <b>نقطة التحقق 4:</b> يقفز خط اللمس في التطبيق وعلى اللوحة.","Speed: شغّل 50 kB، ثم Fast interval + 2M PHY + Long packets وشغّل مرة أخرى. <b>نقطة التحقق 5:</b> عمودان؛ دوّن قيمتي kB/s والفترة التي استخدمها كل تشغيل.","اختياري: نفّذ <code>pnpm tunnel</code> وكرر الخطوات من هاتفك (Chrome على Android، وBluefy على iPhone). قارن سرعته بسرعة Mac."],"note":"لا يزال لا يوجد اقتران: يستطيع أي شخص قريب الاتصال والرسم وقراءة الحساسات. يعمل قفل B4 بالطريقة نفسها هنا إن جمعتهما. لا يرى التطبيق إلا اللوحات التي تختارها في نافذة المتصفح، ويخفي المتصفح بعض الخدمات القياسية عن صفحات الويب عن قصد. تخزّن هواتف iPhone وأجهزة Mac جدول GATT لجهاز ما بحسب عنوانه: إن عرض المستكشف صفوف B3 القديمة، أطفئ البلوتوث ثم شغّله. تعتمد الإنتاجية في الغالب على central: غالبًا ما تكون اللوحة نفسها أسرع 2-4 مرات مع Mac منها مع هاتف."}`),B6:JSON.parse(`{"title":"لوحة مفاتيح ووسائط","heading":"لوحة مفاتيح بلوتوث وريموت لموسيقاك","goal":"تصبح اللوحة لوحة مفاتيح بلوتوث حقيقية: خدمة HID نفسها التي تملكها كل لوحة مفاتيح لاسلكية، فتستخدمها الهواتف وأجهزة Mac والحواسيب بمشغّلها الخاص. يتحول زرها إلى ريموت: تشغيل/إيقاف مؤقت وتخطي الموسيقى على هاتفك (التي قد تعمل على مكبر JBL)، وتغيير مستوى الصوت، والتنقل بين الشرائح، أو كتابة نص ترسله من المراقب التسلسلي. أنت تكتب Report Map الذي يخبر الحاسوب بمعنى بايتاتنا، وترى لماذا لا ترسل لوحة المفاتيح حروفًا أبدًا، بل أرقام مفاتيح فقط.","goalLine":"اقرن اللوحة كلوحة مفاتيح، وتحكّم بموسيقاك بالزر، واكتب نصًا بالتخطيط الصحيح.","goalCheck":["يعرض هاتفك أو Mac الجهاز <b>Bench B6</b> كلوحة مفاتيح متصلة، ويُظهر شريط الحالة على الشاشة القفل (مشفّر) والمفتاح (مربوط).","نقرة في عرض media توقف موسيقاك مؤقتًا وتستأنفها؛ ونقرة مزدوجة تتخطى المقطع؛ ولمس GPIO 2 يرفع الصوت.","<code>type yes</code> يكتب “yes” وليس “zes”: يطابق <code>layout</code> إعداد لوحة مفاتيح الحاسوب.","في عرض keys تستطيع قراءة الضغطة كبايتات: بتات المعدِّلات، ورقم المفتاح، ثم الإفلات بكل أصفار بعدها."],"learn":["HID عبر GATT","report map","أرقام المفاتيح مقابل الحروف","تخطيطات لوحة المفاتيح","consumer control","الربط (bonding)","ريموت الوسائط"],"pins":{"0":{"role":"VCC"},"1":{"role":"BLK"},"2":{"role":"RES"},"3":{"role":"DC"},"4":{"role":"CS"},"5":{"role":"SDA"},"6":{"role":"SCL"},"7":{"role":"GND"},"8":{"role":"BTN"},"9":{"role":"BOOT"}},"commands":{"0":{"does":"يبني المختبر B6 ويرفع البرنامج إلى اللوحة (دون تنزيلات جديدة: جاء NimBLE مع B1).","see":"<code>ble-lab-b6: NimBLE 2.5.1 up</code> و<code>advertising as keyboard \\"Bench B6\\"</code> وقائمة الأوامر. تفتح الشاشة على عرض media: “pair me: Bluetooth settings &gt; Bench B6”.","fix":"“Failed to connect”: اضغط BOOT مطوّلًا، ثم المس RST، ثم اترك BOOT، وشغّل الأمر مرة أخرى."},"1":{"does":"يتصل هاتفك أو Mac، ويقرأ Report Map، ويطلب الاقتران (يحتاج HID إلى تشفير)، ويخزّن ربطًا ليعيد الاتصال من تلقاء نفسه في المرة القادمة.","see":"<code>+ connected</code>، ثم <code>+ secured: Just Works, bonded, key 16 B</code>. يعرض شريط الحالة الحلقات المتصلة وقفلًا بنفسجيًا ومفتاحًا. قد يفتح Mac مساعد إعداد لوحة المفاتيح: أغلقه، أو اضغط المفتاح الذي يطلبه واختر ISO (ألماني) أو ANSI (أمريكي).","fix":"ظاهر لكنه لا يتصل: نفّذ <code>forget</code> هنا و“Forget This Device” على الهاتف، ثم اقرن من جديد. السبب المعتاد هو ربط محفوظ عند طرف واحد فقط."},"2":{"does":"شغّل موسيقى على الهاتف (إلى مكبره أو سماعاته أو JBL). نقرة = تشغيل/إيقاف مؤقت، نقرة مزدوجة = المقطع التالي، ضغطة أقل من 2 s = كتم، ولمس السلك على GPIO 2 / 1 (بعد <code>touch on</code>) = رفع / خفض الصوت.","see":"تتموج الأيقونة، وتسير نقطة من اللوحة إلى الهاتف إلى المكبر، وتستجيب الموسيقى. يطبع المراقب <code>&gt; media key: play/pause (usage 0CD)</code>.","fix":"لا شيء يحدث؟ يجب أن يملك التطبيق تركيز الصوت: شغّل شيئًا أولًا. على Mac تستجيب Music/Spotify؛ وقد لا تستجيب علامة تبويب في المتصفح."},"3":{"does":"افتح Notes (أو أي حقل نص) على الجهاز المقترن، ثم اكتب هذا في المراقب. تضع اللوحة تقريرين لكل حرف في الطابور (ضغط وإفلات) وترسل 6 في كل إطار، بفاصل 8 ms.","see":"يظهر “hello bench” على الهاتف أو Mac. يملأ عرض typer شريط التقدم، ثم يقول <code>typed 11 keys</code>.","fix":"يقول السطر فقط <code>not paired yet</code>؟ اقرن أولًا. الحروف تخرج خاطئة: انظر <code>layout</code>."},"4":{"does":"يخبر اللوحة بالتخطيط المضبوط على الحاسوب، لتختار المفتاح الصحيح لكل حرف. يُحفظ في NVS.","see":"<code>layout German (QWERTZ) (saved)</code>. الآن يعطي <code>type yes</code> الكلمة “yes” على Mac ألماني. الحروف التي يحتاج التخطيط فيها إلى AltGr/Option ‏(@ [ ] { } \\\\ | ~) تُتخطى مع تحذير.","fix":"ما زال y/z مقلوبين: تخطيط الحاسوب هو الآخر. تحقق من قائمة الإدخال في شريط قوائم Mac."},"5":{"does":"مفتاح واحد أو تركيبة: معدِّلات (cmd وctrl وalt وshift) مع مفتاح (enter وtab وesc والأسهم وf1-f12 وحرف).","see":"يفتح Spotlight على Mac (وعلى iPhone مع لوحة مفاتيح، يفتح البحث أيضًا). يعرض عرض keys بايت المعدِّل <code>08</code> (GUI الأيسر) والمفتاح <code>2C</code> (المسافة).","fix":"Windows: يفتح <code>key win+r</code> نافذة Run، و<code>key ctrl+alt+delete</code> شاشة الأمان."},"6":{"does":"يحفظ نصًا في NVS؛ والنقر المزدوج في عرض typer (أو <code>snippet</code> وحده) يكتبه. لوحة ماكرو صغيرة.","see":"<code>snippet saved</code>، والنص في عرض typer.","fix":""},"7":{"does":"افتح عرضًا تقديميًا (Keynote أو PowerPoint أو Google Slides في وضع العرض). نقرة = السهم الأيمن (التالي)، نقرة مزدوجة = السهم الأيسر، ضغطة أقل من 2 s = b (شاشة سوداء).","see":"تنزلق الشريحة على الشاشة من الجهة التي انتقلت إليها؛ وتتبعها الشرائح على الحاسوب.","fix":""},"8":{"does":"آخر التقارير، بايتًا بايتًا: بتات المعدِّلات وأرقام المفاتيح وما تكتبه كل ضغطة بتخطيط اللوحة.","see":"<code>down mod 02 key 04 types 'A'</code> ثم <code>up all zero</code> لحرف A كبير.","fix":""}},"panels":{"0":{"title":"ضغطة مفتاح، من الزر إلى الحرف","intro":"اكتب في الخانة أو اضغط مفتاحًا أدناه وتابعه: تحوّل اللوحة الحرف إلى رقم مفتاح بحسب إعداد التخطيط لديها، وترسل 8 بايتات، ويحوّل الحاسوب الرقم إلى حرف بحسب تخطيطه. اضبط التخطيطين بشكل مختلف واكتب <code>yes</code>: هذا هو الخطأ الذي يصلحه <code>layout de</code>."},"1":{"title":"لماذا لا تستطيع اللوحة التشغيل على مكبر صوتك","intro":"يشغّل JBL الموسيقى عبر صوت البلوتوث الكلاسيكي. لا يملك ESP32-S3 إلا Bluetooth LE، فلا يستطيع البث إليه، لكنه يستطيع أن يكون ريموت الهاتف الذي يفعل ذلك. اضغط مفتاح وسائط لتتبعه، أو جرّب المسار المباشر لترى أين يفشل."},"2":{"title":"ما تعرضه الشاشة","intro":"ستة عروض. media وslides وضعان: فيهما الزر هو الريموت (نقرة، نقرة مزدوجة، ضغط مطوّل)، وضغطة 2 ثانية تنتقل إلى التالي. وفي العروض الأخرى تنتقل النقرة إلى التالي كالمعتاد."}},"steps":["توصيل الشاشة نفسه. اختياري: سلكا توصيل في GPIO 1 وGPIO 2 بطرفين حرّين (مفاتيح لمس للصوت). ارفع <code>ble-lab-b6</code> إلى اللوحة.","على هاتفك أو Mac افتح إعدادات البلوتوث واقرن <b>Bench B6</b>. <b>نقطة التحقق 1:</b> القفل والمفتاح في شريط الحالة، و<code>secured: Just Works, bonded</code> في المراقب.","شغّل موسيقى على الهاتف (إلى JBL إن شئت). في عرض media: نقرة، ثم نقرة مزدوجة. <b>نقطة التحقق 2:</b> تتوقف الموسيقى مؤقتًا وتستأنف وتتخطى المقطع.","اكتب <code>touch on</code> (ارفع يديك عن الأسلاك)، ثم المس سلك GPIO 2. <b>نقطة التحقق 3:</b> يرتفع الصوت.","افتح Notes، واضبط <code>layout</code> ليطابق الحاسوب، ثم <code>type yes, this is the bench</code>. <b>نقطة التحقق 4:</b> يظهر النص نفسه تمامًا.","اضغط الزر 2 s للوصول إلى slides، وافتح عرضًا تقديميًا، وتنقّل فيه بالنقر.","انتقل إلى عرض keys واقرأ ضغطة واحدة: بتات المعدِّلات، ورقم المفتاح، ثم الإفلات."],"note":"عندما يكون iPhone أو iPad متصلًا بلوحة مفاتيح فعلية، تختفي لوحة المفاتيح التي على الشاشة: افصل اللوحة (أو أطفئ البلوتوث) لإعادتها. لإلغاء الاقتران، انسَ اللوحة على الطرفين (<code>forget</code> هنا، و“Forget This Device” هناك). يملك ESP32-S3 Bluetooth LE فقط: لا يستطيع بث الصوت إلى مكبر أو سماعات (هذا بلوتوث كلاسيكي، A2DP)، لذا تتحكم اللوحة بالهاتف ويشغّل الهاتف على JBL. تذهب مفاتيح الصوت والمقطع إلى التطبيق الذي يملك تركيز الصوت. تختلف الأجهزة المضيفة في مكان حروف Option/AltGr، لذا لا يكتب الجدول الألماني إلا ما يستطيع كتابته بالطريقة نفسها على Mac وWindows."}`),B7:{title:`موسيقى`,heading:`آلة MIDI عبر البلوتوث`,goal:`تصبح اللوحة آلة MIDI عبر Bluetooth LE، باستخدام خدمة BLE-MIDI القياسية التي تفهمها GarageBand وAudio MIDI Setup وتطبيقات المُركِّبات على Android وChrome. ينقل MIDI النوتات لا الصوت: المُركِّب (synth) على الجهة الأخرى هو الذي يصنع الصوت (ويمكنه إرساله إلى JBL). اعزف بالزر وبخمسة أسلاك لمس وأوامر المنفذ التسلسلي وآلة إيقاع من 16 خطوة؛ والنوتات المعزوفة على الجهة الأخرى تضيء شريط البيانو في اللوحة وLED. سترى كيف تُحزم النوتات مع الطوابع الزمنية، ولماذا تحدد فترة الاتصال زمن التأخير.`,goalLine:`اعزف نوتات من اللوحة إلى مُركِّب، وشاهد نوتات المُركِّب على اللوحة.`,goalCheck:[`تسرد GarageBand (أو تبويب Music في ble-app) الجهاز <b>Bench B7</b> وتصدر صوتًا عند النقر على الزر.`,`يعزف <code>tune twinkle</code> اللحن؛ ويعزف <code>beat house</code> + <code>seq on</code> الطبول على القناة 10.`,`النوتات التي تعزفها على لوحة مفاتيح المُركِّب تضيء شريط بيانو اللوحة بالأزرق، ويأخذ LED لون كل نوتة.`,`يعرض عرض link فترة اتصالك، وتستطيع أن تقول كم يمكن أن تنتظر النوتة الراديو.`],learn:[`رسائل MIDI`,`حزم BLE-MIDI`,`الطوابع الزمنية`,`running status`,`فترة الاتصال = زمن التأخير`,`اللمس السعوي (capacitive touch)`,`طبول General MIDI`],pins:{0:{role:`VCC`},1:{role:`BLK`},2:{role:`RES`},3:{role:`DC`},4:{role:`CS`},5:{role:`SDA`},6:{role:`SCL`},7:{role:`GND`},8:{role:`BTN`},9:{role:`BOOT`}},commands:{0:{does:`يبني المختبر B7 ويرفع البرنامج إلى اللوحة.`,see:`<code>advertising as MIDI instrument "Bench B7"</code>، وقائمة الأوامر، وعرض keys بخمسة مفاتيح وشريط بيانو.`,fix:`“Failed to connect”: اضغط BOOT مطوّلًا، ثم المس RST، ثم اترك BOOT، وشغّل الأمر مرة أخرى.`},1:{does:`يتصل macOS باللوحة كجهاز MIDI (قد يطلب الاقتران: اقبل). ثم افتح GarageBand بآلة برمجية: فهي تسمع كل أجهزة MIDI.`,see:`<code>+ connected</code> و<code>asked for a 7.5-15 ms interval (low latency)</code> و<code>+ a synth is listening (subscribed)</code>. يقول عرض keys “synth listening”.`,fix:`iPhone/iPad: ‏GarageBand ← افتح لوحة مفاتيح ← الإعدادات (الترس) ← Advanced ← Bluetooth MIDI Devices ← Bench B7. Android: تطبيق BLE-MIDI (مثل “MIDI BLE Connect”) مع أي مُركِّب. Chrome: تبويب Music في ble-app.`},2:{does:`يعزف النوتة التالية من السلم (300 ms). نقرة مزدوجة = وتر. ضغطة أقل من 2 s = إيقاف كل النوتات.`,see:`صوت من GarageBand؛ ويضيء المفتاح بالبنفسجي على شريط البيانو؛ ويرسم المخطط شريطًا بنفسجيًا.`,fix:`لا صوت لكن “synth listening”: في GarageBand اختر مسار آلة برمجية (وليس صوتًا) وارفع مستوى الصوت.`},3:{does:`يجدول لحنًا كاملًا من الملك العام بالإيقاع الحالي. ترسل loop() كل نوتة عند موعدها.`,see:`<code>tune twinkle: 14 notes, 8.4 s</code> واللحن من المُركِّب.`,fix:``},4:{does:`آلة الإيقاع: 4 طبول × 16 خطوة على قناة MIDI رقم 10، حيث يحتفظ General MIDI بالطبول (36 kick و38 snare و42 hi-hat و39 clap).`,see:`يسير مؤشر التشغيل في عرض sequencer على الشبكة؛ وتعزف GarageBand الطبول (اختر مسار طقم طبول للصوت الحقيقي).`,fix:`الطبول تبدو كنوتات بيانو: آلة المسار ليست طقم طبول.`},5:{does:`خمسة أسلاك توصيل على GPIO 1 و2 و6 و13 و14 (أطرافها حرة) تصبح مفاتيح للسلم الخماسي. ارفع يديك أثناء قياس خط الأساس.`,see:`<code>touch on: 5 keys, pentatonic from C4</code>؛ لمس طرف سلك يضيء مفتاحه ويعزف النوتة، ولمسة أقوى = صوت أعلى.`,fix:`GPIO 13 وGPIO 14 هما سلكا RC522 من مسار RFID: افصل القارئ، أو استخدم المفاتيح الثلاثة الأولى.`},6:{does:`ترسل GarageBand (أو بيانو ble-app) رسائل MIDI إلى اللوحة ككتابات.`,see:`مفاتيح زرقاء على شريط البيانو، وأعمدة زرقاء على المخطط، وLED بلون النوتة، وأسطر <code>&lt; note E4 vel 96 ch 1</code>.`,fix:`على Mac لا ترسل GarageBand إلى أجهزة MIDI: استخدم بيانو ble-app، أو محطة DAW بمخرج MIDI.`},7:{does:`يشرح زمن التأخير: تنتظر النوتات حدث الاتصال التالي.`,see:`فترتك (7.5-15 ms إن وافق المضيف، وغالبًا 11.25 أو 15 على أجهزة Apple) وضغطة تنزل إلى النبضة التالية.`,fix:``}},panels:{0:{title:`نوتة واحدة، بايتًا بايتًا`,intro:`اعزف على لوحة المفاتيح الصغيرة (بالنقر، أو بالمفاتيح A إلى K في حاسوبك). النوتات المضغوطة ضمن حدث اتصال واحد تتشارك حزمة واحدة. راقب الرأس والطوابع الزمنية وبايت الحالة وrunning status، الحيلة التي تحذف بايتات الحالة المكررة.`},1:{title:`لماذا تنتظر النوتات: فترة الاتصال`,intro:`لا يجوز للجهاز المتصل أن يتحدث إلا في أحداث الاتصال، حدث واحد في كل فترة. اختر فترة واعزف: كل نوتة تنتظر الحدث التالي. ثم قارن مُركِّبًا يعزف النوتات عند وصولها بآخر يستخدم الطوابع الزمنية.`},2:{title:`ما تعرضه الشاشة`,intro:`خمسة عروض. في keys وsequencer وroll يكون الزر هو الآلة (نقرة لنوتة، نقرة مزدوجة لوتر أو لبدء/إيقاف الطبول، ضغط مطوّل لإيقاف كل النوتات، وضغطة 2 s للانتقال).`}},steps:[`توصيل الشاشة نفسه. اختياري: خمسة أسلاك توصيل في GPIO 1 و2 و6 و13 و14 (افصل RC522 أولًا). ارفع <code>ble-lab-b7</code> إلى اللوحة.`,`اتصل من GarageBand (iPhone/iPad) أو Audio MIDI Setup + GarageBand (Mac) أو تطبيق BLE-MIDI (Android) أو تبويب Music في ble-app (Chrome). <b>نقطة التحقق 1:</b> “synth listening” في عرض keys.`,`انقر الزر بضع مرات، ثم انقر نقرًا مزدوجًا. <b>نقطة التحقق 2:</b> نوتات ووتر من المُركِّب.`,`<code>tune ode</code>، ثم <code>beat funk</code> و<code>seq on</code>. <b>نقطة التحقق 3:</b> لحن وإيقاع طبول.`,`اعزف على لوحة مفاتيح المُركِّب. <b>نقطة التحقق 4:</b> مفاتيح زرقاء وLED ملوّن على اللوحة.`,`افتح عرض link واقرأ فترتك. جرّب <code>bpm 200</code> مع الطبول واستمع: هل ما زال الإيقاع مضبوطًا؟`],note:`MIDI تعليمات لا صوت: لا تصدر اللوحة أي صوت بنفسها (ليس لها مكبر). ويمكن لصوت المُركِّب أن يذهب إلى أي مكان يستطيع التشغيل فيه، ومنه JBL، عبر بلوتوث الهاتف أو Mac نفسه. تمنح أجهزة Apple عادةً فترات اتصال 11.25-15 ms لـ MIDI، فتنتظر النوتة حتى فترة كاملة؛ وتتيح الطوابع الزمنية داخل كل حزمة لمُركِّب جيد أن يحافظ على الإيقاع رغم ذلك. إن طلب Mac الاقتران فاقبل: تسمح اللوحة بربط Just Works. المضمّن هنا ألحان من الملك العام فقط.`},B8:JSON.parse(`{"title":"المضيف","heading":"بدّل الأدوار: لوحة مفاتيحك تكتب على اللوحة","goal":"حتى الآن كان الهاتف أو الحاسوب المحمول هو central وكانت اللوحة تجيب. هنا تصبح اللوحة هي central، كما هو حاسوبك المحمول. تجد الأجهزة القابلة للاتصال، وتتصل بها، وتستكشف جداول GATT لديها (للقراءة فقط: الأساسيات العامة مثل الاسم والمصنّع والبطارية). ثم تستضيف لوحة مفاتيح BLE وفأرة BLE خاصتك: تقترن (تعرض اللوحة رمز مرور وتكتبه أنت على لوحة المفاتيح)، وتقرأ وصف لوحة المفاتيح لتقاريرها (Report Map)، وتشترك، وتحوّل البايتات الخام إلى نص ومؤشر رسم على الشاشة.","goalLine":"اقرن لوحة مفاتيح BLE باللوحة، واكتب على شاشتها، وافهم كل بايت ترسله لوحة المفاتيح.","goalCheck":["ينتهي <code>host</code> بـ <code>+ hosting: keyboard media keys</code> (أو <code>mouse</code>) بعد كتابة رمز المرور على لوحة المفاتيح.","ما تكتبه يظهر في عرض <b>keyboard</b>؛ وتضيء Shift وCtrl وAlt وCmd أثناء الضغط عليها؛ ويبدّل <code>layout de</code> بين Y وZ ويعرض ä ö ü ß.","في عرض <b>reports</b> تستطيع تسمية كل بايت ملوّن: المعدِّلات (كهرماني)، ورموز المفاتيح (أخضر مزرق)، وX للفأرة (أزرق)، وY (بنفسجي)، والعجلة (مرجاني).","بعد إعادة تشغيل الطاقة تعيد اللوحة الاتصال بلوحة المفاتيح المربوطة من تلقاء نفسها، دون رمز مرور."],"learn":["دور central","اكتشاف الخدمات","HID عبر GATT ‏(HOGP)","تحليل Report Map","إدخال رمز المرور كـ central","الاشتراك في CCCD","رموز المفاتيح مقابل التخطيطات","الربط وإعادة الاتصال"],"pins":{"0":{"role":"VCC"},"1":{"role":"BLK"},"2":{"role":"RES"},"3":{"role":"DC"},"4":{"role":"CS"},"5":{"role":"SDA"},"6":{"role":"SCL"},"7":{"role":"GND"},"8":{"role":"BTN"},"9":{"role":"BOOT"}},"commands":{"0":{"does":"يبني المختبر B8 ويرفع البرنامج إلى اللوحة. مكتبة NimBLE-Arduino محمّلة من قبل (B1).","see":"<code>ble-lab-b8: NimBLE 2.5.1 up, address …</code>، وقائمة الأوامر، وعرض <b>devices</b> يمتلئ.","fix":"“Failed to connect”: اضغط BOOT مطوّلًا، ثم المس RST، ثم اترك BOOT، وشغّل الأمر مرة أخرى."},"1":{"does":"يفتح المراقب التسلسلي (ويعيد تشغيل اللوحة).","see":"<code>Bluetooth lab B8 Host (ble-lab-b8)</code> والأوامر.","fix":""},"2":{"does":"لوحة المفاتيح المقترنة بالفعل بجهاز Mac لا تتحدث إلا معه. يجعلها وضع الاقتران تعلن لأي أحد: عادةً اضغط مفتاح البلوتوث أو القناة 3 s حتى يومض ضوؤها بسرعة. لوحات المفاتيح متعددة القنوات: اختر قناة لا يستخدمها Mac.","see":"عرض <b>devices</b>: لوحة مفاتيحك قرب الأعلى مع أيقونة لوحة مفاتيح و<b>HID</b>.","fix":"غير موجودة: ما زالت متصلة بـ Mac (بدّل القناة، أو أزلها من إعدادات البلوتوث في Mac). تستخدم Apple Magic Keyboard البلوتوث الكلاسيكي ولا تظهر هنا أبدًا."},"3":{"does":"يطبع الأجهزة القابلة للاتصال، الأقوى أولًا. تُستثنى المنارات: لا يمكن الاتصال بها.","see":"<code>  1   -48 dBm  keyboard/mouse  C4:7D:2A:91:0E:33  Bench Keys  [HID]</code>","fix":""},"4":{"does":"يرسل CONNECT_IND إلى الجهاز 1 (فتختار اللوحة الآن توقيت الاتصال)، ثم يستكشف: يكتشف كل خدمة وخاصية وواصف ويقرأ الأساسيات العامة.","see":"<code>&gt; CONNECT_IND to Bench Keys</code> و<code>+ connected: we are the central</code> و<code>+ 5 services, 19 characteristics in 820 ms</code> و<code>- it is a keyboard/mouse (1812): type host</code>. يعرض عرض <b>explore</b> الشجرة؛ وتقول قيم HID “locked until paired”.","fix":"<code>no answer from …</code>: توقف عن الإعلان (ينتهي وضع الاقتران بعد نحو 60 s): ابدأه من جديد."},"5":{"does":"يقترن (ربط + رمز مرور + Secure Connections)، ويقرأ Report Map، ويجد كل تقرير إدخال عبر واصفه 2908 ويشترك (يكتب 01 00 في CCCD الخاص به).","see":"ستة أرقام كبيرة على الشاشة و<code>! type 482915 on the keyboard, then Enter</code>. اكتبها على لوحة المفاتيح، واضغط Enter: ‏<code>+ secured: passkey, bonded, key 16 B</code> و<code>&lt; Report Map: 72 bytes, 11 input fields</code> و<code>&gt; CCCD 01 00: report 1 (keyboard)</code> و<code>+ hosting: keyboard media keys</code>. ينتقل العرض إلى <b>keyboard</b>.","fix":"<code>pairing failed</code>: غادرت لوحة المفاتيح وضع الاقتران، أو ما زال لديها ربط قديم مع اللوحة: نفّذ <code>forget</code>، وأزلها من جهة لوحة المفاتيح (وضع الاقتران مرة أخرى)، ثم <code>connect</code> و<code>host</code>."},"6":{"does":"كل ضغطة مفتاح إشعار: تقارنه اللوحة بالسابق وتضيف المفاتيح المضغوطة حديثًا. Backspace يحذف، وEnter يبدأ سطرًا جديدًا، وEsc يمسح.","see":"نصك في عرض <b>keyboard</b> مع مؤشر وامض؛ وتضيء أغطية المعدِّلات بالكهرماني ما دمت تضغط Shift أو Ctrl أو Alt أو Cmd؛ وتعرض مفاتيح الوسائط إشعارًا بنفسجيًا.","fix":"حروف خاطئة (y وz مقلوبان)؟ انظر الأمر التالي."},"7":{"does":"رموز المفاتيح مواضع لا حروف. تحوّلها اللوحة إلى حروف بالتخطيط الذي تختاره: أمريكي أو ألماني.","see":"<code>- layout German (QWERTZ): the same keys, other letters</code>. الآن يعطي المفتاح المطبوع عليه Z الحرف z، وتظهر ä ö ü ß.","fix":""},"8":{"does":"تقارير الإدخال الخام، الأحدث في الأسفل، وكل بايت ملوّن بحسب حقل Report Map الذي ينتمي إليه.","see":"<code>#1 kbd 02 00 0B 00 00 00 00 00</code> مع 02 بالكهرماني (Left Shift) و0B بالأخضر المزرق (المفتاح H)، والسطر المفكوك تحته.","fix":""},"9":{"does":"Boot protocol: الصيغة الثابتة من 8 بايتات التي يفهمها كل BIOS، دون قراءة Report Map. قارنها ببروتوكول التقارير.","see":"<code>&gt; CCCD 01 00: report 0 (boot keyboard)</code> وصفوف <code>bootK</code> في عرض reports. يعيد <code>boot off</code> الوضع السابق.","fix":"<code>no Protocol Mode: this device has no boot mode</code>: بعض لوحات المفاتيح لا تقدمه."},"10":{"does":"الفأرة بلا مفاتيح وبلا شاشة، لذا يعود الاقتران إلى Just Works (بلا أرقام). يصف Report Map الخاص بها الأزرار وX وY والعجلة بأي أحجام بتات تشاء.","see":"<code>+ secured: Just Works, bonded</code> و<code>+ hosting: mouse</code> وعرض <b>mouse</b>: الزر الأيسر يرسم، والأيمن يغيّر اللون، والأوسط يمسح، والعجلة تضبط الفرشاة.","fix":"يعدو المؤشر عبر الشاشة: هذه الفأرة تبلّغ بخطوات كبيرة؛ وتنصّفها اللوحة بالفعل."},"11":{"does":"يُحفظ الربط (المفاتيح) في NVS. عندما تعلن لوحة المفاتيح من جديد (اضغط مفتاحًا لإيقاظها) تتعرف اللوحة على عنوانها وتعيد الاتصال.","see":"<code>+ bonded Bench Keys is back: reconnecting</code>، ثم <code>+ secured: …</code> دون رمز مرور، و<code>+ hosting</code>.","fix":"قد لا يُتعرف على لوحات المفاتيح التي تختبئ خلف عنوان خاص متغير (RPA): نفّذ <code>connect</code> + <code>host</code> يدويًا حينئذ."},"12":{"does":"استكشف جهازًا ليس لوحة مفاتيح. لا تُقرأ إلا الأساسيات العامة، ولا يُكتب شيء.","see":"بضع خدمات، أغلبها UUID طويل واحد من المصنّع، و<code>- JBL app's own service only: audio uses Classic BT</code>. لا يمر الصوت نفسه عبر BLE على هذا المكبر، ولا تدعم هذه الشريحة البلوتوث الكلاسيكي.","fix":"غير موجود في القائمة: لا يعلن عبر BLE إلا بينما يبحث تطبيق JBL عنه، أو بعد التشغيل مباشرة."},"13":{"does":"يحذف كل ربط على اللوحة.","see":"<code>- every bond deleted: pair again to use a keyboard</code>. أزل اللوحة من جهة لوحة المفاتيح أيضًا (وضع الاقتران)، وإلا سترفض الاقتران التالي.","fix":""}},"panels":{"0":{"title":"من المسح إلى ضغطة المفتاح، خطوة بخطوة","intro":"كل ما يحدث بين إعلان لوحة المفاتيح وظهور الحرف <b>h</b> على اللوحة، حزمة بحزمة. اختر قصة: الاقتران الأول، أو العودة بعد إعادة تشغيل الطاقة، أو استكشاف مكبر JBL. استخدم ◀ ▶ أو دعها تعمل؛ ويعرض الصندوق تحت كل خطوة البايتات الحقيقية."},"1":{"title":"فُكّ تقريرًا بنفسك","intro":"لا ترسل لوحة المفاتيح حروفًا أبدًا، بل مواضع مفاتيح وبتات فقط. اختر Report Map، ثم اضغط مفاتيح على لوحة المفاتيح الصغيرة أو اسحب على لوحة الفأرة: يطير التقرير إلى اللوحة ويضيء كل حقل بدوره، مع عنصر Report Map الذي عرّفه. بدّل بين US/DE: يصبح رمز المفتاح نفسه حرفًا آخر."},"2":{"title":"ما تعرضه الشاشة","intro":"سبعة عروض. النقرة تنتقل إلى العرض التالي، والنقر المزدوج ينفذ الإجراء أسفل اليسار، والضغط المطوّل يخطو الخطوة التالية: connect، ثم host، ثم disconnect."}},"steps":["التوصيل نفسه كما في كل مختبرات BLE (الشاشة؛ وزر الضغط اختياري). ارفع <code>ble-lab-b8</code> إلى اللوحة وافتح المراقب.","ضع لوحة مفاتيح BLE في وضع الاقتران على قناة لا يستخدمها Mac. <b>نقطة التحقق 1:</b> تظهر في عرض <b>devices</b> مع <b>HID</b>.","<code>connect 1</code> (أو انقر نقرًا مزدوجًا لاختياره، ثم ضغطة مطوّلة). <b>نقطة التحقق 2:</b> يسرد عرض <b>explore</b> الخدمات 1800 و180A و180F و1812 Human Interface Device مع خصائص Report الخاصة بها.","<code>host</code> (أو ضغطة مطوّلة). اكتب الأرقام الستة على لوحة المفاتيح واضغط Enter. <b>نقطة التحقق 3:</b> ‏<code>+ hosting: keyboard</code> وعرض <b>keyboard</b>.","اكتب جملة، واضغط Shift مطوّلًا، وجرّب Backspace وEnter. إن كانت لديك لوحة مفاتيح ألمانية: <code>layout de</code>. <b>نقطة التحقق 4:</b> نصك على TFT، بما فيه الحروف المعدّلة.","انتقل إلى <b>reports</b> وسمِّ كل بايت ملوّن؛ وقارن مع “فُكّ تقريرًا بنفسك” أعلاه. ثم <code>boot on</code> و<code>host</code>: ‏8 بايتات ثابتة.","اختياري: <code>disconnect</code>، واقرن فأرتك بالطريقة نفسها وارسم في عرض <b>mouse</b>.","افصل اللوحة وأعد توصيلها، ثم اضغط مفتاحًا على لوحة المفاتيح. <b>نقطة التحقق 5:</b> تعيد الاتصال وتستضيف دون رمز مرور.","استكشف مكبر JBL: ‏<code>connect &lt;n&gt;</code>. وانظر لماذا لا يُظهر شيئًا عن الصوت."],"note":"لا يتصل الاستكشاف إلا بالأجهزة التي تختارها ولا يقرأ إلا القيم العامة القياسية (الاسم والمظهر والمصنّع والطراز والبرنامج الثابت والبطارية وPnP ID)؛ ولا يكتب إلى أي جهاز، إلا إعدادي HID القياسيين على لوحة مفاتيح أو فأرة تستضيفها (CCCD للاشتراك، وProtocol Mode لوضع boot). اتصل بأجهزتك الخاصة فقط. اتصال واحد في كل مرة: اقطع الاتصال قبل الاتصال بالجهاز التالي. قد تتوقف لوحة مفاتيح مربوطة باللوحة عن العمل مع Mac على تلك القناة حتى تقرنها هناك من جديد. يستخدم عرض keyboard الخط المدمج في الشاشة، وفيه ä ö ü Ä Ö Ü ß لكن بلا €. لا يضع BLE معرّف التقرير في الإشعار: فهو في واصف Report Reference ‏(2908)، ولهذا تبدأ البايتات في عرض reports بالبيانات."}`)};export{e as default};
//# sourceMappingURL=ble-BgmFynpa.js.map